function check(input, actual, expected) {
  const [arr] = input;
  const n = arr.length;
  if (!Array.isArray(actual) || actual.length !== 2 || !actual.every(Number.isInteger)) return false;
  const [i, j] = actual;
  if (expected[0] === -1) return i === -1 && j === -1;
  if (i < 0 || i + 1 >= j || j > n - 1) return false;
  // Compare the pieces as bit strings with their leading zeros removed.
  const value = (from, to) => arr.slice(from, to).join('').replace(/^0+/, '');
  const first = value(0, i + 1);
  return first === value(i + 1, j) && first === value(j, n);
}

