function threeEqualParts(arr) {
  const n = arr.length;
  let ones = 0;
  for (const bit of arr) {
    ones += bit;
  }
  if (ones === 0) {
    return [0, n - 1];
  }
  if (ones % 3 !== 0) {
    return [-1, -1];
  }
  const each = ones / 3;
  let first = -1;
  let second = -1;
  let third = -1;
  let count = 0;
  for (let k = 0; k < n; k++) {
    if (arr[k] === 1) {
      if (count === 0) {
        first = k;
      } else if (count === each) {
        second = k;
      } else if (count === 2 * each) {
        third = k;
      }
      count++;
    }
  }
  while (third < n && arr[first] === arr[second] && arr[second] === arr[third]) {
    first++;
    second++;
    third++;
  }
  if (third === n) {
    return [first - 1, second];
  }
  return [-1, -1];
}

