function generate(rand, size) {
  const big = size === 'large';
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const zeros = k => Array(k).fill(0);
  const mode = rand();
  if (mode < 0.15) return [zeros(big ? int(1500, 2000) : int(3, 10))];
  if (mode < 0.65) {
    // Three copies of one pattern, each after its own run of leading zeros: a split exists.
    const length = big ? int(300, 600) : int(1, 4);
    const pattern = [1];
    while (pattern.length < length) pattern.push(rand() < 0.5 ? 1 : 0);
    const arr = [];
    for (let part = 0; part < 3; part++) arr.push(...zeros(int(0, big ? 50 : 2)), ...pattern);
    // Sometimes flip one bit so that the pieces almost match.
    if (rand() < 0.35) {
      const k = int(0, arr.length - 1);
      arr[k] = 1 - arr[k];
    }
    return [arr];
  }
  const n = big ? int(1500, 2000) : int(3, 12);
  const density = 0.2 + rand() * 0.6;
  return [Array.from({ length: n }, () => (rand() < density ? 1 : 0))];
}
